import React from "react";

const Result = ({ result, onReset }) => {
  const { style, decade, item } = result;

  // You can map styles to Pinterest embed IDs
  const pinterestEmbeds = {
    "Modern Classic": "16818198602263405",
    "Boho Chic": "16818198602263410",
    "Streetwear": "16818198602263415",
    // Add more styles and Pinterest IDs here
  };

  // Default fallback Pinterest ID
  const embedId = pinterestEmbeds[style] || "16818198602263405";

  return (
    <div style={{ maxWidth: "400px", margin: "0 auto", textAlign: "center" }}>
      <h2>🎨 Your Style DNA</h2>
      <p><strong>Style:</strong> {style}</p>
      <p><strong>Decade:</strong> {decade}</p>
      <p><strong>Item:</strong> {item}</p>

      <iframe
        src={`https://assets.pinterest.com/ext/embed.html?id=${embedId}`}
        height="714"
        width="345"
        frameBorder="0"
        scrolling="no"
        title={`${style} Outfit`}
        style={{ borderRadius: "12px", margin: "20px auto" }}
      ></iframe>

      <button onClick={onReset} style={{ marginTop: "20px", padding: "10px 20px", borderRadius: "6px", border: "1px solid #ccc", backgroundColor: "#f0f0f0" }}>
        🔁 Take Quiz Again
      </button>
    </div>
  );
};

export default Result;
